							<div col="col-md-12">
								<p>
									Trend following works in the stock market. While standard
									trend following strategies that involve moving averages and
									golden/death crosses do not significantly outperform buy and
									hold in the long run, they do reduce investors’ drawdowns
									during big stock market crashes.
								</p>
								<p>
									To further increase returns, a trend follower can
									“supercharge” their portfolio by being exposed to a more
									aggressive index than the S&amp;P 500, like the NASDAQ
									Composite.
								</p>
								<p>
									Of course, entirely buying the NASDAQ Composite instead of the
									S&amp;P 500 would increase your gains and losses since the
									NASDAQ Composite isn’t significantly better than the S&amp;P
									500 on a risk-adjusted basis.
								</p>
								<p>
									So to supercharge your portfolio during an uptrend without
									increasing both gains and losses by a similar amount, we can
									combine 2 different trends and timeframes for the 2 indices.
								</p>
								<ol>
									<li>
										When the NASDAQ Composite is in a “short term uptrend”, go
										long the NASDAQ Composite regardless of what the S&amp;P 500
										is doing.
									</li>
									<li>
										When the NASDAQ Composite is not in a “short term uptrend”
										BUT the S&amp;P 500 is in a “long term uptrend”, go long the
										S&amp;P 500.
									</li>
									<li>
										When the NASDAQ Composite is not in a “short term uptrend”
										and the S&amp;P 500 is not in a “long term uptrend”, do not
										buy stocks.
									</li>
								</ol>
								<h3>Model’s rules</h3>
								<ol>
									<li>
										If the NASDAQ Composite is &gt; its 30 day moving average,
										go long the NASDAQ Composite.
									</li>
									<li>
										If the NASDAQ Composite is &lt;= its 30 day moving average
										AND the S&amp;P 500’s 50 dma is &gt; its 200 dma, go long
										the S&amp;P 500.
									</li>
									<li>Otherwise, SELL.</li>
								</ol>
								<h3>You can do 1 of 7 things when you SELL:</h3>
								<ol>
									<li>Model: Shift into 100% cash</li>
									<li>Model (long/short S&amp;P): Short the S&amp;P 500</li>
									<li>Model (long/short NASDAQ): Short the NASDAQ Composite</li>
									<li>
										Model (Multi-Asset Aggregate Bonds): Buy and hold a
										Aggregate Bond ETF (AGG)
									</li>
									<li>
										Model (Multi-Asset Corporate Bonds): Buy and hold a US
										Corporate Bond ETF (LQD)
									</li>
									<li>
										Model (Multi-Asset Treasury Bonds): Buy and hold a US
										Treasury Bond ETF (TLT)
									</li>
									<li>Model (Gold): Buy and hold a Gold ETF (GLD)</li>
								</ol>

								<h3>Performance</h3>
								<ul>
									<li>Last updated March 2024</li>
									<li>
										Backtest timeframe: <b>2006-07-01 to 2024-03-31</b>. NOTE:
										These dates were chosen to provide the same coverage across
										all signals and ETF's used in those signals and are
										dependant on ETF start dates.
									</li>
									<li>
										For all backtests shown, we used active and accessible ETF's
										(e.g., SPY, QQQ, TLT, LQD, etc). The prices of these ETF's
										are split and dividend adjusted.
									</li>

									<li>
										Shorting is performed by buying inverse ETFs. For these
										backtests, we used SH to short the S&amp;P500 and PSQ to
										short the NASDAQ. Using leveraged ETFs like SSO (2x) and
										UPRO (3x) may increase your returns and drawdowns. NOTE: For
										the REIT Trading Model, no shorting is done as their isn't
										an ETF with enough history and activity to cover the
										timeframe.
									</li>

									<li>
										Historical returns shown below include transaction fees of
										$1.5 per order (e.g., $3 per round-trip) but does not
										include slippage.
									</li>
								</ul>

